function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}let favorites=read('scrl-favorites',[]),projects=read('scrl-projects',[]),category='All templates',view='discover',reverse=false,design=null,current=0;let cache=new Map(),paint=0;
function persist(){try{localStorage.setItem('scrl-projects',JSON.stringify(projects));localStorage.setItem('scrl-favorites',JSON.stringify(favorites));return true}catch{toast('Storage is full. Export your slide before closing.');return false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function render(){const query=$('#search').value.trim().toLowerCase();let list=view==='projects'?projects:view==='favorites'?templates.filter(t=>favorites.includes(t.id)):templates;list=list.filter(t=>(category==='All templates'||t.cat===category||category==='Carousels')&&(t.name+' '+t.cat).toLowerCase().includes(query));if(reverse)list=[...list].reverse();$('#grid').replaceChildren();list.forEach(t=>{const card=document.createElement('article');card.className='card';const art=document.createElement('div');art.className='artwork '+t.style;art.tabIndex=0;art.setAttribute('role','button');art.setAttribute('aria-label','Edit '+t.name);const img=document.createElement('img');img.src=t.image||t.slides?.[0]?.image||'';img.alt=t.name;art.append(img);const text=document.createElement('div');text.className='card-text';text.textContent=t.title||t.slides?.[0]?.title||t.name;art.append(text);const badge=document.createElement('span');badge.className='badge';badge.textContent=view==='projects'?'SAVED':t.tag;art.append(badge);if(view!=='projects'){const fav=document.createElement('button');fav.className='favorite';fav.textContent=favorites.includes(t.id)?'♥':'♡';fav.setAttribute('aria-label','Favorite '+t.name);fav.setAttribute('aria-pressed',String(favorites.includes(t.id)));fav.onclick=e=>{e.stopPropagation();favorites=favorites.includes(t.id)?favorites.filter(id=>id!==t.id):[...favorites,t.id];persist();render()};art.append(fav)}const open=()=>openEditor(t,view==='projects');art.onclick=open;art.onkeydown=e=>{if(e.target!==art)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}};card.append(art);const info=document.createElement('div');info.className='card-info';const name=document.createElement('span');name.textContent=t.name;const count=document.createElement('small');count.textContent=(t.slides?.length||3)+' slides';info.append(name,count);card.append(info);const desc=document.createElement('p');desc.textContent=t.cat+' / '+(t.style==='film'?'Analog textures':'Editable carousel');card.append(desc);$('#grid').append(card)});$('#empty').hidden=list.length>0;$('#project-count').textContent=projects.length}
['All templates','Carousels','Minimal','Travel','Lifestyle','Film'].forEach(cat=>{const b=document.createElement('button');b.textContent=cat;b.className=cat===category?'active':'';b.onclick=()=>{category=cat;$('#filters').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()};$('#filters').append(b)});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#page-name').textContent=b.querySelector('span').textContent;$('#heading').textContent=view==='discover'?'Make something worth sharing.':view==='projects'?'Your ideas, brought to life.':'A little saved inspiration.';$('#subtitle').textContent=view==='projects'?'Pick up where you left off. Your next story is waiting.':'Your next great post starts here. Let’s bring it to life.';$('#hero').hidden=view!=='discover';$('#section-title').textContent=view==='projects'?'Your projects':view==='favorites'?'Your favorites':'Find your starting point ↙';render()});
$('#search').oninput=render;$('#sort').onclick=()=>{reverse=!reverse;$('#sort').textContent=reverse?'↕  Reverse order':'↕  Recommended';render()};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))$('#search').focus()}});
function openEditor(t=templates[0],existing=false){design=existing?structuredClone(t):{id:crypto.randomUUID(),name:t.name,cat:t.cat,style:t.style,format:'portrait',slides:[{title:t.title,caption:t.caption,bg:t.bg,color:t.color,image:t.image},{title:'The little\nthings.',caption:'TAKE A MOMENT. TAKE IT ALL IN.',bg:t.bg,color:t.color,image:templates[(t.id||1)%templates.length].image},{title:'Stay a little\nlonger.',caption:'SAVE THIS MOMENT',bg:t.bg,color:t.color,image:t.image}]};current=0;$('#design-name').value=design.name;$('#format').value=design.format;sync();$('#editor').showModal()}
function blank(){openEditor({...templates[1],name:'Untitled story',title:'Your story\nstarts here.',caption:'MAKE IT YOURS',image:''});design.slides=[design.slides[0]];sync()}
['#new','#start','#blank'].forEach(s=>$(s).onclick=blank);$('#hero-create').onclick=()=>openEditor(templates[0]);$('#close').onclick=()=>{save(false);$('#editor').close()};$('#editor').addEventListener('cancel',()=>save(false));$('#help').onclick=()=>toast('Choose a template, edit each slide, then export your story as PNG.');$('#pro').onclick=()=>toast('All studio templates are free to use in this preview.');
function sync(){const s=design.slides[current];$('#title-input').value=s.title;$('#caption-input').value=s.caption;$('#bg-input').value=s.bg;$('#color-input').value=s.color;$('#slides').replaceChildren();design.slides.forEach((_,i)=>{const b=document.createElement('button');b.textContent=i+1;b.className=i===current?'active':'';b.onclick=()=>{current=i;sync()};$('#slides').append(b)});$('#slide-label').textContent=`Slide ${current+1} of ${design.slides.length}`;$('#remove').disabled=design.slides.length===1;draw()}
function loadImage(src){if(!src)return Promise.resolve(null);if(cache.has(src))return cache.get(src);const p=new Promise(resolve=>{const img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=src});cache.set(src,p);return p}
async function draw(){const version=++paint,s={...design.slides[current]},c=$('#canvas'),ctx=c.getContext('2d'),image=await loadImage(s.image);if(version!==paint)return;c.width=1080;c.height=design.format==='square'?1080:design.format==='story'?1920:1350;const w=c.width,h=c.height;ctx.fillStyle=s.bg;ctx.fillRect(0,0,w,h);const cover=(x,y,pw,ph)=>{if(!image)return;const ratio=Math.max(pw/image.width,ph/image.height),sw=pw/ratio,sh=ph/ratio;ctx.drawImage(image,(image.width-sw)/2,(image.height-sh)/2,sw,sh,x,y,pw,ph)};if(design.style==='editorial'){cover(0,0,w,h);ctx.fillStyle='#00000055';ctx.fillRect(0,0,w,h)}else if(design.style==='minimal'){cover(130,h*.5,w-260,h*.39)}else{ctx.fillStyle='#faf7ed';ctx.fillRect(65,65,w-130,h*.69);cover(90,90,w-180,h*.65)}ctx.fillStyle=s.color;ctx.textAlign='center';const lines=s.title.split('\n');let size=design.style==='minimal'?145:design.style==='editorial'?165:110;ctx.font=`italic ${size}px Georgia`;while(lines.some(l=>ctx.measureText(l).width>w-130)&&size>35){size-=5;ctx.font=`italic ${size}px Georgia`}const base=design.style==='minimal'?h*.17:design.style==='editorial'?h*.44:(design.format==='square'?h*.79:h*.84);lines.forEach((l,i)=>ctx.fillText(l,w/2,base+i*size*1.06));ctx.font='18px Arial';ctx.fillText(s.caption,w/2,h-57);ctx.font='16px Arial';ctx.fillText(`${String(current+1).padStart(2,'0')} / ${String(design.slides.length).padStart(2,'0')}`,w/2,40)}
[['#title-input','title'],['#caption-input','caption'],['#bg-input','bg'],['#color-input','color']].forEach(([sel,key])=>$(sel).oninput=()=>{design.slides[current][key]=$(sel).value;draw()});$('#format').onchange=()=>{design.format=$('#format').value;draw()};$('#add').onclick=()=>{if(design.slides.length>=20)return toast('Your carousel can have up to 20 slides.');design.slides.push({...design.slides[current],title:'A new\nchapter.'});current=design.slides.length-1;sync()};$('#remove').onclick=()=>{if(design.slides.length===1)return;design.slides.splice(current,1);current=Math.min(current,design.slides.length-1);sync()};
$('#upload').onclick=()=>$('#file').click();$('#upload-nav').onclick=()=>{blank();$('#file').click()};$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image file.');const reader=new FileReader();reader.onload=async()=>{const img=await loadImage(reader.result);if(!img)return toast('This image could not be opened. Try JPG or PNG.');const c=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(img.width,img.height));c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);design.slides[current].image=c.toDataURL('image/jpeg',.85);draw()};reader.readAsDataURL(file);e.target.value=''};
function save(notify=true){design.name=$('#design-name').value.trim()||'Untitled story';const index=projects.findIndex(p=>p.id===design.id);if(index<0)projects.unshift(structuredClone(design));else projects[index]=structuredClone(design);if(persist()&&notify)toast('Project saved. Come back to it anytime.');render()};$('#save').onclick=()=>save();$('#export').onclick=async()=>{await draw();try{const blob=await new Promise(resolve=>$('#canvas').toBlob(resolve,'image/png'));if(!blob)throw Error();const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`${($('#design-name').value||'story').replace(/[^a-z0-9-]/gi,'-')}-${current+1}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);save(false);toast('Your slide is ready. Keep creating.')}catch{toast('Export unavailable for this photo. Upload a local image and try again.')}};render();
